import { colors, radius } from "./source.ts";

const HEADER =
  "Generated by packages/core/scripts/tokens.ts from src/tokens/source.ts. Do not edit.";

/** The web theme: CSS variables plus Tailwind v4's `@theme inline` mapping. */
export function themeCss(): string {
  const vars = Object.entries(colors).map(([name, value]) => `  --${name}: ${value};`);
  const theme = Object.keys(colors).map((name) => `  --color-${name}: var(--${name});`);
  const radii = Object.entries(radius).map(
    ([name, px]) => `  --radius-${name}: ${px}px;`,
  );
  return [
    `/* ${HEADER} */`,
    ":root {",
    ...vars,
    `  --radius: ${radius.lg}px;`,
    "}",
    "",
    "@theme inline {",
    ...theme,
    ...radii,
    "}",
    "",
  ].join("\n");
}

/** The native theme: the same values, as a typed module. */
export function nativeTheme(): string {
  return [
    `// ${HEADER}`,
    "",
    `export const colors = ${JSON.stringify(colors, null, 2)} as const;`,
    "",
    `export const radius = ${JSON.stringify(radius, null, 2)} as const;`,
    "",
  ].join("\n");
}
